"use strict";

const fs = require('fs');
const path = require('path');
const https = require('https');

const COUNTER_PATH = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'session_counter.json');
const OPENCLAW_CONFIG_PATH = path.join(process.env.HOME, '.openclaw', 'openclaw.json');
const COACH_TELEGRAM_CHAT_ID = '6124913915';

// 閾值設定
const WARN_YELLOW = 20;  // 🟡 警戒
const WARN_ORANGE = 30;  // 🟠 警告，準備交接
const WARN_RED    = 38;  // 🔴 危急，立即搶救

function readCounter() {
  try {
    if (!fs.existsSync(COUNTER_PATH)) return { round: 0, bootstrapTime: new Date().toISOString() };
    return JSON.parse(fs.readFileSync(COUNTER_PATH, 'utf-8'));
  } catch (e) {
    return { round: 0, bootstrapTime: new Date().toISOString() };
  }
}

function writeCounter(data) {
  try {
    const dir = path.dirname(COUNTER_PATH);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(COUNTER_PATH, JSON.stringify(data));
  } catch (e) {}
}

// 2026-07-10 軍師加：直接發 Telegram，不依賴 event.context.inject（已知 message:preprocessed
// 是 fire-and-forget，inject 不會被模型看到，見 memory: feedback_openclaw_hook_fire_and_forget.md）。
// 這是「鎖」——不管模型有沒有注意到注入的文字，教練一定會收到這則訊息。
function sendTelegramDirect(text) {
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, 'utf-8'));
    const botToken = cfg?.channels?.telegram?.accounts?.bot_main?.botToken;
    if (!botToken) return;

    const payload = JSON.stringify({ chat_id: COACH_TELEGRAM_CHAT_ID, text: text });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/sendMessage`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
      timeout: 8000,
    }, (res) => { res.on('data', () => {}); });
    req.on('error', () => {});
    req.on('timeout', () => req.destroy());
    req.write(payload);
    req.end();
  } catch (e) {
    // 靜默失敗，不影響對話主流程
  }
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const counter = readCounter();
  counter.round = (counter.round || 0) + 1;

  const round = counter.round;
  let warning = null;

  if (round >= WARN_RED) {
    warning = {
      level: '🔴',
      text: [
        '# 🔴 危急：Context 即將溢出',
        `> 本次 Session 已進行第 **${round}** 輪對話，距離強制刷新只剩 ${Math.max(0, 45 - round)} 輪以內。`,
        '',
        '**你現在必須立即執行：**',
        '1. 把「最近 5 輪對話在聊什麼」濃縮成 500 字以內的摘要，寫到 `~/.openclaw/workspace/state/session_handoff.md`（格式見下）',
        '2. 更新 HEARTBEAT.md（寫入當前任務進度、未完成事項）',
        '3. git commit && git push（確保記憶不遺失）',
        '4. 教練已經收到系統直發的 Telegram 通知，不需要你再另外發一次',
        '5. 等待教練確認後再繼續',
        '',
        '## session_handoff.md 格式（500字以內）',
        '```',
        '# 對話交接摘要',
        '> 寫入時間：{當下時間}',
        '',
        '## 剛才在聊什麼',
        '{用 3-5 個要點列出最近討論的主題和結論}',
        '',
        '## 教練正在等什麼',
        '{教練最後一個問題或指令是什麼，我承諾要做什麼}',
        '',
        '## 未完成的事',
        '{列出還沒做完的任務}',
        '```',
        '',
        '⚠️ 絕對不可在未通知教練的情況下繼續對話直到溢出。',
        '⚠️ session_handoff.md 是新 session 啟動時的第一份記憶，寫不好 = 下一個你一問三不知。',
      ].join('\n'),
    };
    if (!counter.notifiedRed) {
      sendTelegramDirect(`🔴 教練，對話已進行第 ${round} 輪，快滿了。我正在自動把重點存進記憶檔，準備交接，請您準備開新對話。`);
      counter.notifiedRed = true;
    }
  } else if (round >= WARN_ORANGE) {
    warning = {
      level: '🟠',
      text: [
        '# 🟠 警告：準備 Context 交接',
        `> 本次 Session 已進行第 **${round}** 輪，距離危急線還有 ${WARN_RED - round} 輪。`,
        '',
        '**請在本輪回覆結尾完成：**',
        '1. 把「這場 session 在聊什麼」濃縮成 500 字以內摘要，寫到 `~/.openclaw/workspace/state/session_handoff.md`',
        '   （包含：剛才聊什麼、教練正在等什麼、未完成的事）',
        '2. 更新 HEARTBEAT.md（記錄當前進度）',
        '3. git commit 確保狀態已存',
        '4. 教練已經收到系統直發的 Telegram 通知',
      ].join('\n'),
    };
    if (!counter.notifiedOrange) {
      sendTelegramDirect(`🟠 教練，對話已進行第 ${round} 輪，容量用得差不多了，我會開始整理重點準備交接，建議您有空可以開新對話。`);
      counter.notifiedOrange = true;
    }
  } else if (round >= WARN_YELLOW) {
    warning = {
      level: '🟡',
      text: [
        `# 🟡 警戒：Session 已進行第 ${round} 輪`,
        `> 距離警告線（${WARN_ORANGE}輪）還有 ${WARN_ORANGE - round} 輪，距離危急線還有 ${WARN_RED - round} 輪。`,
        '',
        '請在回覆結尾附上健康度尾巴：',
        `\`━━━ 健康度 🟡 輪 #${round} | 距離刷新線：${WARN_RED - round}輪\``,
      ].join('\n'),
    };
  }

  writeCounter(counter);

  if (warning) {
    if (!event.context.inject) event.context.inject = [];
    if (Array.isArray(event.context.inject)) {
      event.context.inject.push({ role: 'system', content: warning.text });
    }
  }
};

module.exports = handler;
module.exports.default = handler;

