"use strict";

const fs = require("fs");
const path = require("path");
const https = require("https");

const NAMECARD_FOLDER = "/Volumes/home/名片媒合中心";
const STATE_PATH = path.join(process.env.HOME, ".openclaw", "hooks", "namecard-inbound", "processed.json");
const LOG_PATH = path.join(process.env.HOME, ".openclaw", "hooks", "namecard-inbound", "inbound.log");
const OPENCLAW_CONFIG_PATH = path.join(process.env.HOME, ".openclaw", "openclaw.json");
const COACH_TELEGRAM_CHAT_ID = "6124913915";
const MAX_PROCESSED = 200;

const IMAGE_EXTS = new Set([".jpg", ".jpeg", ".png", ".heic", ".heif", ".webp"]);

function log(line) {
  try {
    fs.appendFileSync(LOG_PATH, `[${new Date().toISOString()}] ${line}\n`);
  } catch (e) {
    // ignore
  }
}

function readProcessed() {
  try {
    if (!fs.existsSync(STATE_PATH)) return [];
    return JSON.parse(fs.readFileSync(STATE_PATH, "utf-8"));
  } catch (e) {
    return [];
  }
}

function writeProcessed(list) {
  try {
    fs.mkdirSync(path.dirname(STATE_PATH), { recursive: true });
    fs.writeFileSync(STATE_PATH, JSON.stringify(list.slice(-MAX_PROCESSED)));
  } catch (e) {
    // ignore
  }
}

function isImage(mediaPath, mediaType) {
  if (mediaType && String(mediaType).toLowerCase().startsWith("image/")) return true;
  const ext = path.extname(mediaPath || "").toLowerCase();
  return IMAGE_EXTS.has(ext);
}

function hasTrigger(text) {
  return typeof text === "string" && text.includes("名片");
}

function sendTelegramDirect(text) {
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, "utf-8"));
    const botToken = cfg?.channels?.telegram?.accounts?.bot_main?.botToken;
    if (!botToken) return;

    const payload = JSON.stringify({ chat_id: COACH_TELEGRAM_CHAT_ID, text });
    const req = https.request(
      {
        hostname: "api.telegram.org",
        path: `/bot${botToken}/sendMessage`,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(payload),
        },
        timeout: 8000,
      },
      (res) => {
        res.on("data", () => {});
      }
    );
    req.on("error", () => {});
    req.on("timeout", () => req.destroy());
    req.write(payload);
    req.end();
  } catch (e) {
    // 靜默失敗，不影響對話主流程
  }
}

function timestampSlug() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}

const handler = async (event) => {
  if (!event || typeof event !== "object") return;
  if (event.type !== "message" || event.action !== "preprocessed") return;
  if (!event.context || typeof event.context !== "object") return;

  const ctx = event.context;
  const mediaPath = ctx.mediaPath;
  const mediaType = ctx.mediaType;
  const text = ctx.bodyForAgent || ctx.body || "";

  if (!mediaPath) return;
  if (!isImage(mediaPath, mediaType)) return;
  if (!hasTrigger(text)) return;

  // 冪等：同一則訊息（mediaPath+messageId）不重複處理
  const dedupeKey = `${ctx.messageId || ""}:${mediaPath}`;
  const processed = readProcessed();
  if (processed.includes(dedupeKey)) return;

  try {
    if (!fs.existsSync(mediaPath)) {
      log(`SKIP 來源檔案不存在: ${mediaPath}`);
      return;
    }
    if (!fs.existsSync(NAMECARD_FOLDER)) {
      log(`FAIL 目的資料夾不存在（Amber SMB可能沒掛載）: ${NAMECARD_FOLDER}`);
      sendTelegramDirect(
        `🔴 教練，收到您傳的名片照片，但無法存進辨識資料夾（Amber私有雲可能斷線），請檢查 SMB 連線。原始照片仍在：${mediaPath}`
      );
      return;
    }

    const ext = path.extname(mediaPath) || ".jpg";
    const channel = ctx.channelId || "unknown";
    const destName = `${timestampSlug()}-${channel}${ext}`;
    const destPath = path.join(NAMECARD_FOLDER, destName);

    fs.copyFileSync(mediaPath, destPath);
    log(`OK 複製成功: ${mediaPath} -> ${destPath}（來源頻道: ${channel}）`);

    processed.push(dedupeKey);
    writeProcessed(processed);
  } catch (e) {
    log(`FAIL 複製失敗: ${e && e.message}`);
    sendTelegramDirect(`🔴 教練，收到您傳的名片照片，但轉存失敗：${e && e.message}。原始照片仍在：${mediaPath}`);
  }
};

module.exports = handler;
module.exports.default = handler;

